/* Apex Horizon Capital - live dashboard. Data: data/ledger.json + data/ic.json (generated by
   publish_dashboard.py from the firm's files) + free keyless CORS APIs polled in the browser. */
"use strict";
const REFRESH_S = 30, DATA_REFRESH_S = 300, TZ = "Europe/Oslo";
const S = { L: null, meta: null, IC: null, q: {}, prev: {}, charts: {}, lastUpd: null, countdown: REFRESH_S, firstLoad: true };

/* ---------- formatting ---------- */
const esc = s => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const eur = (v, d = 2) => v == null || isNaN(v) ? "—" : "€" + Number(v).toLocaleString("en-GB", { minimumFractionDigits: d, maximumFractionDigits: d });
const sgnEur = v => v == null || isNaN(v) ? "—" : (v >= 0 ? "+" : "−") + eur(Math.abs(v));
const pct = (v, d = 2, sign = false) => v == null || isNaN(v) ? "—" : (sign && v >= 0 ? "+" : v < 0 ? "−" : "") + Math.abs(v).toFixed(d) + "%";
const num = (v, d = 2) => v == null || isNaN(v) ? "—" : Number(v).toLocaleString("en-GB", { minimumFractionDigits: d, maximumFractionDigits: d });
const cls = v => v > 0 ? "up" : v < 0 ? "dn" : "";
const tfmt = (iso, withDate = true) => {
  if (!iso) return "—"; const d = new Date(iso); if (isNaN(d)) return esc(iso);
  return d.toLocaleString("en-GB", { timeZone: TZ, ...(withDate ? { day: "2-digit", month: "short" } : {}), hour: "2-digit", minute: "2-digit", hour12: false });
};
const tfull = iso => tfmt(iso) + ' <span class="tz">CET</span>';
const ago = iso => { const s = (Date.now() - new Date(iso)) / 1000; if (isNaN(s)) return ""; if (s < 90) return Math.round(s) + " s ago"; if (s < 5400) return Math.round(s / 60) + " min ago"; if (s < 172800) return Math.round(s / 3600) + " h ago"; return Math.round(s / 86400) + " d ago"; };
const $ = id => document.getElementById(id);

/* ---------- live price sources (all keyless + CORS, verified from headless Chromium) ---------- */
async function getJSON(url, ms = 9000) {
  const c = new AbortController(); const t = setTimeout(() => c.abort(), ms);
  try { const r = await fetch(url, { signal: c.signal, cache: "no-store" }); if (!r.ok) throw new Error("HTTP " + r.status); return await r.json(); }
  finally { clearTimeout(t); }
}
const onvista = (type, isin, prefer) => async () => {
  const j = await getJSON(`https://api.onvista.de/api/v1/instruments/${type}/ISIN:${isin}/snapshot`);
  const list = (j.quoteList && j.quoteList.list) || [];
  for (const code of prefer) {
    const q = list.find(x => x.market && x.market.codeMarket === code && x.isoCurrency === "EUR" && x.last != null);
    if (q) return { px: +q.last, time: q.datetimeLast, src: `onvista · ${q.market.name}` };
  }
  throw new Error("no EUR quote");
};
const SOURCES = {
  "SXR8.DE": [onvista("FUND", "IE00B5BMR087", ["_GER"])],            // Xetra, same line as the ledger's SXR8.DE marks
  "APC.F": [onvista("STOCK", "US0378331005", ["_FRA", "_GAT"])],      // Frankfurt (APC.F), Tradegate as backup
  "EURUSD": [
    async () => { const j = await getJSON("https://api.kraken.com/0/public/Ticker?pair=EURUSD"); const r = j.result.ZEURZUSD; return { px: +r.c[0], time: new Date().toISOString(), src: "Kraken spot EUR/USD (last trade)", polled: true }; },
    async () => { const j = await getJSON("https://api.frankfurter.dev/v1/latest?base=EUR&symbols=USD"); return { px: +j.rates.USD, time: j.date + "T16:00:00+01:00", src: "Frankfurter (ECB reference, daily)", daily: true }; },
    async () => { const j = await getJSON("https://open.er-api.com/v6/latest/EUR"); return { px: +j.rates.USD, time: new Date(j.time_last_update_unix * 1000).toISOString(), src: "open.er-api (daily)", daily: true }; },
  ],
  "BTCUSDT": [
    async () => { const j = await getJSON("https://api.binance.com/api/v3/ticker/price?symbol=BTCUSDT"); return { px: +j.price, time: new Date().toISOString(), src: "Binance spot", polled: true }; },
    async () => { const j = await getJSON("https://data-api.binance.vision/api/v3/ticker/price?symbol=BTCUSDT"); return { px: +j.price, time: new Date().toISOString(), src: "Binance (data-api mirror)", polled: true }; },
    async () => { const j = await getJSON("https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd&include_last_updated_at=true"); return { px: +j.bitcoin.usd, time: new Date(j.bitcoin.last_updated_at * 1000).toISOString(), src: "CoinGecko (USD)" }; },
  ],
  "BTC4H": [
    async () => { const k = await getJSON("https://data-api.binance.vision/api/v3/klines?symbol=BTCUSDT&interval=4h&limit=3"); const b = k[k.length - 2]; return { px: +b[4], time: new Date(b[6] + 1).toISOString(), src: "Binance 4h kline (last closed)" }; },
    async () => { const k = await getJSON("https://api.binance.com/api/v3/klines?symbol=BTCUSDT&interval=4h&limit=3"); const b = k[k.length - 2]; return { px: +b[4], time: new Date(b[6] + 1).toISOString(), src: "Binance 4h kline (last closed)" }; },
  ],
  "BTC-EUR": [
    async () => { const j = await getJSON("https://api.exchange.coinbase.com/products/BTC-EUR/ticker"); return { px: +j.price, time: j.time, src: "Coinbase Exchange" }; },
    async () => { const j = await getJSON("https://api.kraken.com/0/public/Ticker?pair=XBTEUR"); return { px: +j.result.XXBTZEUR.c[0], time: new Date().toISOString(), src: "Kraken spot", polled: true }; },
  ],
  "ETHUSDT": [async () => { const j = await getJSON("https://api.binance.com/api/v3/ticker/price?symbol=ETHUSDT"); return { px: +j.price, time: new Date().toISOString(), src: "Binance spot", polled: true }; }],
  "SOLUSDT": [async () => { const j = await getJSON("https://api.binance.com/api/v3/ticker/price?symbol=SOLUSDT"); return { px: +j.price, time: new Date().toISOString(), src: "Binance spot", polled: true }; }],
  "EURNOK": [async () => { const j = await getJSON("https://api.frankfurter.dev/v1/latest?base=EUR&symbols=NOK"); return { px: +j.rates.NOK, time: j.date + "T16:00:00+01:00", src: "Frankfurter (ECB reference, daily)", daily: true }; }],
};
const TAPE = [
  { k: "SXR8.DE", label: "SXR8 · S&P 500 UCITS", d: 2, ccy: "€" }, { k: "APC.F", label: "Apple · APC.F", d: 2, ccy: "€" },
  { k: "EURUSD", label: "EUR/USD", d: 5, ccy: "" }, { k: "BTCUSDT", label: "BTC/USDT", d: 2, ccy: "$" },
  { k: "BTC-EUR", label: "BTC/EUR", d: 2, ccy: "€" }, { k: "ETHUSDT", label: "ETH/USDT", d: 2, ccy: "$" },
  { k: "SOLUSDT", label: "SOL/USDT", d: 3, ccy: "$" }, { k: "EURNOK", label: "EUR/NOK", d: 4, ccy: "" },
];

function ledgerFallback(k) {
  const p = (S.L.positions || []).find(p => p.symbol === k);
  if (p) return { px: p.last_price, time: p.last_price_time, src: `last mark (${p.price_source || "ledger"})`, fallback: true };
  if (k === "BTC4H") { const o = (S.L.pending_orders || [])[0]; if (o && o.last_check) return { px: o.last_check.last_closed_4h, time: o.last_check.time, src: "last mark (ledger)", fallback: true }; }
  return null;
}
async function fetchQuote(k) {
  for (const f of SOURCES[k] || []) { try { const r = await f(); if (r && isFinite(r.px) && r.px > 0) return { ...r, live: true }; } catch (e) { /* try next */ } }
  return ledgerFallback(k);
}
async function refreshPrices() {
  if (S.busy) return; S.busy = true; S.countdown = REFRESH_S;
  try {
  const keys = Object.keys(SOURCES);
  const res = await Promise.all(keys.map(fetchQuote));
  keys.forEach((k, i) => { if (S.q[k]) S.prev[k] = S.q[k].px; if (res[i]) S.q[k] = res[i]; });
  S.lastUpd = new Date().toISOString(); S.countdown = REFRESH_S;
  renderLive();
  } finally { S.busy = false; }
}

/* ---------- portfolio maths (same formulas as mark.py) ---------- */
const FEE = 1.0;
function livePositions() {
  return S.L.positions.map(p => {
    const q = S.q[p.symbol]; const px = q ? q.px : p.last_price; const fx = p.asset_class === "FX";
    let mv, upl;
    if (fx) { mv = 0; upl = p.side === "short" ? p.qty * (p.entry_price / px - 1) : p.qty * (px / p.entry_price - 1); }
    else { mv = p.qty * px; upl = mv - p.qty * p.entry_price; }
    const risk = fx ? Math.abs(p.qty * (px / p.stop - 1)) : (p.side === "long" ? p.qty * (px - p.stop) + FEE : 0);
    const dir = p.side === "long" ? 1 : -1;
    const dStop = (px / p.stop - 1) * 100 * dir, dTgt = p.target ? (p.target / px - 1) * 100 * dir : null;
    const notional = fx ? p.notional_eur : mv;
    const prog = p.target ? (px - p.stop) / (p.target - p.stop) : null, entProg = p.target ? (p.entry_price - p.stop) / (p.target - p.stop) : null;
    const uplPct = fx ? upl / p.notional_eur * 100 : upl / (p.qty * p.entry_price) * 100;
    return { ...p, px, q, mv, upl, uplPct, risk, dStop, dTgt, notional, prog, entProg, fx };
  });
}
function portfolio() {
  const P = livePositions(), L = S.L;
  const equity = L.cash + P.reduce((a, p) => a + (p.fx ? p.upl : p.mv), 0);
  const hist = L.equity_history || []; const peak = Math.max(...hist.map(h => h.equity), equity);
  const dd = (equity / peak - 1) * 100;
  const gross = P.reduce((a, p) => a + p.notional, 0), risk = P.reduce((a, p) => a + p.risk, 0);
  const todayOslo = new Date().toLocaleDateString("en-CA", { timeZone: TZ });
  const prevDay = hist.filter(h => new Date(h.time).toLocaleDateString("en-CA", { timeZone: TZ }) < todayOslo);
  const dayBase = prevDay.length ? prevDay[prevDay.length - 1].equity : L.starting_capital;
  const usd = P.filter(p => /US|USD|Apple/i.test(p.theme + p.name)).reduce((a, p) => a + p.notional, 0);
  const crypto = P.filter(p => p.asset_class === "Crypto").reduce((a, p) => a + p.notional, 0);
  const maxPos = P.reduce((m, p) => Math.max(m, p.notional / equity * 100), 0);
  const maxPosSym = (P.find(p => p.notional / equity * 100 === maxPos) || {}).symbol;
  const maxTradeRisk = P.reduce((m, p) => Math.max(m, p.risk), 0);
  return { P, equity, peak, dd, gross, risk, dayBase, usd, crypto, maxPos, maxPosSym, maxTradeRisk,
    pnl: equity - L.starting_capital, pnlPct: (equity / L.starting_capital - 1) * 100 };
}

/* ---------- rendering: live parts ---------- */
function bar(v, lim, warnAt = 0.7) { const f = Math.max(0, Math.min(1, v / lim)); const c = f >= 1 ? "var(--dn)" : f >= warnAt ? "var(--warn)" : "var(--up)"; return `<div class="bar"><i style="width:${(f * 100).toFixed(1)}%;background:${c}"></i></div>`; }
function renderKPIs(pf) {
  const R = S.meta.rules, L = S.L;
  const k = [
    { l: "Equity", v: eur(pf.equity), s: `start ${eur(L.starting_capital, 0)} · day <span class="${cls(pf.equity - pf.dayBase)}">${sgnEur(pf.equity - pf.dayBase)}</span>`, hl: 1 },
    { l: "Total P&L", v: `<span class="${cls(pf.pnl)}">${sgnEur(pf.pnl)}</span>`, s: `<span class="${cls(pf.pnl)}">${pct(pf.pnlPct, 2, true)}</span> since inception ${tfmt(L.inception, true)}` },
    { l: "Cash", v: eur(L.cash), s: `${pct(L.cash / pf.equity * 100, 1)} of equity · dry powder` },
    { l: "Gross exposure", v: eur(pf.gross), s: `${pct(pf.gross / pf.equity * 100, 1)} of equity · ${(pf.gross / pf.equity).toFixed(2)}x / ${R.max_leverage}x max` , b: bar(pf.gross / pf.equity, R.max_leverage) },
    { l: "Risk at stops", v: eur(pf.risk), s: `${pct(pf.risk / pf.equity * 100)} of equity · limit ${R.total_stop_risk_pct}%`, b: bar(pf.risk / pf.equity * 100, R.total_stop_risk_pct) },
    { l: "Drawdown", v: `<span class="${pf.dd < 0 ? "dn" : ""}">${pct(pf.dd, 2)}</span>`, s: `peak ${eur(pf.peak)} · kill-switch −${R.kill_switch_dd_pct}% (${eur(L.starting_capital * (1 - R.kill_switch_dd_pct / 100), 0)})`, b: bar(-pf.dd, R.kill_switch_dd_pct) },
  ];
  $("kpis").innerHTML = k.map(x => `<div class="kpi ${x.hl ? "hl" : ""}"><div class="l">${x.l}</div><div class="v num">${x.v}</div><div class="s">${x.s}</div>${x.b || ""}</div>`).join("");
}
function srcLine(q) {
  if (!q) return '<span class="dn">no price</span>';
  const tag = q.fallback ? '<span class="pill warn">last mark</span>' : q.daily ? '<span class="pill info">daily ref</span>' : '<span class="pill ok">live</span>';
  const when = q.fallback ? `last mark ${tfmt(q.time)} CET` : q.polled ? `polled ${tfmt(q.time)} CET` : `print ${tfmt(q.time)} CET · ${ago(q.time)}`;
  return `${tag} ${esc(q.src)}<br>${when}`;
}
function renderTape() {
  $("tape").innerHTML = TAPE.map(t => {
    const q = S.q[t.k]; const pv = S.prev[t.k]; const fl = q && pv != null && q.px !== pv ? (q.px > pv ? "flash-up" : "flash-dn") : "";
    return `<div class="tick ${fl}"><div class="sym">${esc(t.label)}</div><div class="px num">${q ? t.ccy + num(q.px, t.d) : "—"}</div><div class="src">${srcLine(q)}</div></div>`;
  }).join("");
}
function progBar(p) {
  if (p.prog == null) return "";
  const c = Math.max(0, Math.min(1, p.prog)), e = Math.max(0, Math.min(1, p.entProg));
  const col = p.upl >= 0 ? "var(--up)" : "var(--dn)";
  return `<div class="prog" title="stop → target"><span class="entry" style="left:${(e * 100).toFixed(1)}%"></span><span class="cur" style="left:${(c * 100).toFixed(1)}%;background:${col}"></span></div>
    <div class="prog-l"><span>stop ${num(p.stop, p.fx ? 5 : 2)}</span><span>${(c * 100).toFixed(0)}% of way</span><span>target ${num(p.target, p.fx ? 5 : 2)}</span></div>`;
}
function renderPositions(pf) {
  const rows = pf.P.map(p => {
    const d = p.fx ? 5 : 2, q = p.q;
    return `<tr>
      <td class="sym-cell"><b>${esc(p.symbol)} <span class="pill ${p.side === "long" ? "ok" : "bad"}">${p.side.toUpperCase()}</span></b><span>${esc(p.name)}</span><span>${esc(p.theme)} · ${esc(p.asset_class)}</span><span class="rat">${esc(p.rationale)}</span></td>
      <td data-l="Qty" class="num">${p.fx ? eur(p.qty, 0) + " notional" : num(p.qty, 4)}</td>
      <td data-l="Entry" class="num">${p.fx ? num(p.entry_price, 5) : eur(p.entry_price)}</td>
      <td data-l="Live" class="num"><b>${p.fx ? num(p.px, 5) : eur(p.px)}</b><div class="small muted" style="white-space:normal">${q ? (q.fallback ? "last mark " + tfmt(q.time) : esc(q.src) + " · " + tfmt(q.time)) : ""}</div></td>
      <td data-l="Value / notional" class="num">${eur(p.notional)}<div class="small muted">${pct(p.notional / pf.equity * 100, 1)} of equity</div></td>
      <td data-l="Unrealised P&L" class="num ${cls(p.upl)}"><b>${sgnEur(p.upl)}</b><div class="small">${pct(p.uplPct, 2, true)}</div></td>
      <td data-l="To stop" class="num">${pct(p.dStop)}</td>
      <td data-l="To target" class="num">${pct(p.dTgt)}</td>
      <td data-l="Open risk" class="num">${eur(p.risk)}<div class="small muted">${pct(p.risk / pf.equity * 100)} eq.</div></td>
      <td data-l="Stop → target" class="full" style="min-width:170px">${progBar(p)}</td>
    </tr>`;
  }).join("");
  $("positions-table").innerHTML = `<div class="tscroll"><table class="stack"><thead><tr><th>Instrument</th><th>Qty</th><th>Entry</th><th>Live</th><th>Value</th><th>Unreal. P&L</th><th>To stop</th><th>To target</th><th>Open risk</th><th>Stop → target</th></tr></thead><tbody>${rows}</tbody></table></div>`;
  $("pos-note").textContent = `${pf.P.length} open · entries ${tfmt(S.L.positions[0] && S.L.positions[0].entry_time)} CET`;
}
function renderPending() {
  const os = S.L.pending_orders || [];
  if (!os.length) { $("pending").innerHTML = '<div class="muted">No pending orders.</div>'; return; }
  $("pending").innerHTML = os.map(o => {
    const spot = S.q.BTCUSDT, k4 = S.q.BTC4H, eurq = S.q["BTC-EUR"];
    const ref = o.ref_price_at_creation ? o.ref_price_at_creation[0] : null;
    const cur = k4 ? k4.px : null, sp = spot ? spot.px : null;
    const dist = cur ? (o.trigger_usdt / cur - 1) * 100 : null, distSpot = sp ? (o.trigger_usdt / sp - 1) * 100 : null;
    const progress = ref && sp ? Math.max(0, Math.min(1, (sp - ref) / (o.trigger_usdt - ref))) : 0;
    const trig = cur && cur > o.trigger_usdt;
    return `<div class="pend">
      <div><h3>${esc(o.symbol)} <span class="pill ${trig ? "bad" : "vio"}">${trig ? "TRIGGER CONDITION MET → IC" : esc(o.status).toUpperCase()}</span></h3>
        <div class="small muted">${esc(o.type)}</div>
        <dl class="kv" style="margin-top:10px"><dt>Rule</dt><dd>${esc(o.trigger_rule)}</dd><dt>Trigger</dt><dd class="num">${num(o.trigger_usdt, 0)} USDT (4h close)</dd>
        <dt>Max size</dt><dd>${eur(o.max_size_eur, 0)}</dd><dt>Stop rule</dt><dd>${esc(o.stop_rule)}</dd><dt>Created</dt><dd>${tfull(o.created)}${ref ? " at " + num(ref, 2) + " USDT" : ""}</dd></dl></div>
      <div>
        <div class="stats" style="margin:0 0 6px"><div class="stat"><div class="l">Last closed 4h</div><div class="v num">${cur ? num(cur, 2) : "—"}</div><div class="l">${k4 ? (k4.fallback ? "last mark " : "closed ") + tfmt(k4.time) + " CET" : ""}</div></div>
          <div class="stat"><div class="l">Distance to trigger (4h close)</div><div class="v num ${dist > 0 ? "wn" : "up"}">${pct(dist, 2, true)}</div><div class="l">needs a 4h close above ${num(o.trigger_usdt, 0)}</div></div>
          <div class="stat"><div class="l">BTC spot</div><div class="v num">${sp ? "$" + num(sp, 2) : "—"}</div><div class="l">${spot ? esc(spot.src) : ""} · ${pct(distSpot, 2, true)} to trigger${eurq ? " · " + eur(eurq.px) : ""}</div></div></div>
        <div class="bigprog"><i style="width:${(progress * 100).toFixed(1)}%"></i></div>
        <div class="prog-l"><span>created ${ref ? num(ref, 0) : ""}</span><span>${(progress * 100).toFixed(0)}% of the way (spot)</span><span>trigger ${num(o.trigger_usdt, 0)}</span></div>
        ${o.last_check ? `<div class="small muted" style="margin-top:6px">Ledger check: last closed 4h ${num(o.last_check.last_closed_4h, 2)} at ${tfmt(o.last_check.time)} CET</div>` : ""}
      </div></div>`;
  }).join("<hr style='border-color:var(--line)'>");
}
function gauge(id, val, lim, fmt, label, sub, invert) {
  return { id, val, lim, fmt, label, sub, invert };
}
function renderGauges(pf) {
  const R = S.meta.rules, eq = pf.equity;
  const G = [
    gauge("g1", pf.maxPos, R.per_position_cap_pct, v => pct(v, 1), "Largest position", `${esc(pf.maxPosSym || "")} notional vs ${R.per_position_cap_pct}% cap · on live equity`),
    gauge("g2", pf.maxTradeRisk / eq * 100, R.per_trade_risk_pct, v => pct(v, 2), "Max per-trade risk", `${eur(pf.maxTradeRisk)} vs ${R.per_trade_risk_pct}% (${eur(R.per_trade_risk_eur, 0)})`),
    gauge("g3", pf.risk / eq * 100, R.total_stop_risk_pct, v => pct(v, 2), "Total risk at stops", `${eur(pf.risk)} vs ${R.total_stop_risk_pct}% limit`),
    gauge("g4", -pf.dd, R.kill_switch_dd_pct, v => pct(-v, 2), "Drawdown", `vs −${R.kill_switch_dd_pct}% kill-switch`),
    gauge("g5", pf.gross / eq, R.max_leverage, v => v.toFixed(2) + "x", "Gross leverage", `vs ${R.max_leverage}x max`),
    gauge("g6", pf.crypto / eq * 100, R.crypto_cap_pct, v => pct(v, 1), "Crypto exposure", `vs ${R.crypto_cap_pct}% cap`),
  ];
  if (!S.charts.gauges) {
    $("gauges").innerHTML = G.map(g => `<div class="gauge"><div class="gw"><canvas id="${g.id}"></canvas><div class="gv num" id="${g.id}v"></div></div><div class="gl">${g.label}</div><div class="gs" id="${g.id}s"></div></div>`).join("")
      + `<div class="gauge"><div class="gw" style="display:grid;place-items:center"><div><div class="num" style="font-size:22px;font-weight:700;color:var(--warn)" id="usdv"></div><div class="gs">of equity</div></div></div><div class="gl">USD exposure</div><div class="gs">no cap · accepted by the Chairman (26 Nov 08:20)</div></div>`;
    S.charts.gauges = G.map(g => new Chart($(g.id), { type: "doughnut", data: { datasets: [{ data: [0, 1], backgroundColor: ["#22d3a6", "#1e293b"], borderWidth: 0 }] },
      options: { responsive: true, maintainAspectRatio: false, rotation: -90, circumference: 180, cutout: "74%", animation: { duration: 500 }, plugins: { legend: { display: false }, tooltip: { enabled: false } } } }));
  }
  G.forEach((g, i) => {
    const f = Math.max(0, Math.min(1, g.val / g.lim)); const col = f >= 1 ? "#f43f5e" : f >= 0.7 ? "#f59e0b" : "#22d3a6";
    const ch = S.charts.gauges[i]; ch.data.datasets[0].data = [f, 1 - f]; ch.data.datasets[0].backgroundColor = [col, "#1e293b"]; ch.update();
    $(g.id + "v").textContent = g.fmt(g.val); $(g.id + "v").style.color = col; $(g.id + "s").innerHTML = g.sub + ` · ${(f * 100).toFixed(0)}% used`;
  });
  $("usdv").textContent = pct(pf.usd / eq * 100, 1);
  const notes = [];
  const head = S.meta.rules.total_stop_risk_pct / 100 * eq - pf.risk;
  notes.push(`<div class="note info">Risk headroom before the ${R.total_stop_risk_pct}% total-stop limit: <b>${eur(head)}</b>${head < R.per_trade_risk_eur ? ` — less than one full ${eur(R.per_trade_risk_eur, 0)} trade slot, so any new trade must be sized down.` : "."}</div>`);
  if (pf.dd <= -R.kill_switch_dd_pct) notes.push(`<div class="note" style="border-color:var(--dn)"><b>KILL-SWITCH:</b> drawdown beyond −${R.kill_switch_dd_pct}%. CRO orders flatten.</div>`);
  pf.P.forEach(p => { if (p.dStop < 1) notes.push(`<div class="note"><b>${esc(p.symbol)}</b> is within 1% of its stop (${pct(p.dStop)}).</div>`); });
  notes.push(`<div class="note">CRO flag on record: SXR8, Apple and the EUR/USD short all lose together on a USD reversal. The Chairman accepted the USD concentration for growth (ruling 26 Nov 08:20 CET).</div>`);
  $("risk-notes").innerHTML = notes.join("");
}
const PAL = ["#22d3a6", "#3b82f6", "#a78bfa", "#f59e0b", "#f43f5e", "#64748b"];
function renderAlloc(pf) {
  const items = pf.P.map(p => ({ l: p.symbol + (p.fx ? " (notional)" : ""), v: p.notional })).concat([{ l: "Cash", v: S.L.cash }]);
  const total = items.reduce((a, x) => a + x.v, 0);
  if (!S.charts.alloc) {
    S.charts.alloc = new Chart($("allocChart"), { type: "doughnut", data: { labels: [], datasets: [{ data: [], backgroundColor: PAL, borderColor: "#0f172a", borderWidth: 3 }] },
      options: { responsive: true, maintainAspectRatio: false, cutout: "66%", plugins: { legend: { display: false }, tooltip: { callbacks: { label: c => ` ${c.label}: ${eur(c.raw)} (${(c.raw / total * 100).toFixed(1)}%)` } } } } });
  }
  const c = S.charts.alloc; c.data.labels = items.map(x => x.l); c.data.datasets[0].data = items.map(x => +x.v.toFixed(2)); c.update();
  $("alloc-legend").innerHTML = items.map((x, i) => `<div><span><i style="background:${PAL[i]}"></i>${esc(x.l)}</span><span class="num">${eur(x.v)} · ${(x.v / pf.equity * 100).toFixed(1)}% eq.</span></div>`).join("");
}
function renderEquity(pf) {
  const h = (S.L.equity_history || []).map(x => ({ t: x.time, v: x.equity, note: x.note }));
  const pts = h.concat([{ t: S.lastUpd || new Date().toISOString(), v: +pf.equity.toFixed(2), live: true }]);
  const labels = pts.map(p => (p.live ? "LIVE " : "") + tfmt(p.t));
  const data = pts.map(p => p.v);
  if (!S.charts.eq) {
    const ctx = $("equityChart").getContext("2d"); const g = ctx.createLinearGradient(0, 0, 0, 300); g.addColorStop(0, "#22d3a640"); g.addColorStop(1, "#22d3a600");
    S.charts.eq = new Chart(ctx, { type: "line", data: { labels: [], datasets: [
        { label: "Equity €", data: [], borderColor: "#22d3a6", backgroundColor: g, fill: true, tension: .25, pointRadius: 4, pointHoverRadius: 6, pointBackgroundColor: [] },
        { label: "Starting capital", data: [], borderColor: "#64748b", borderDash: [5, 5], pointRadius: 0, borderWidth: 1 }] },
      options: { responsive: true, maintainAspectRatio: false, interaction: { mode: "index", intersect: false },
        scales: { x: { ticks: { color: "#8b9ab3", maxRotation: 0, autoSkip: true, maxTicksLimit: 6 }, grid: { color: "#1e293b" } },
                  y: { ticks: { color: "#8b9ab3", callback: v => "€" + v }, grid: { color: "#1e293b" } } },
        plugins: { legend: { labels: { color: "#cbd5e1", boxWidth: 12 } }, tooltip: { callbacks: { label: c => ` ${c.dataset.label}: ${eur(c.raw)}` } } } } });
  }
  const c = S.charts.eq; c.data.labels = labels; c.data.datasets[0].data = data;
  c.data.datasets[0].pointBackgroundColor = pts.map(p => p.live ? "#f59e0b" : "#22d3a6");
  c.data.datasets[1].data = pts.map(() => S.L.starting_capital); c.update();
  $("eq-note").innerHTML = `${h.length} marks from ledger + live point (amber) · CET`;
}
function renderLive() {
  if (!S.L) return;
  const pf = portfolio();
  renderKPIs(pf); renderTape(); renderPositions(pf); renderPending(); renderGauges(pf); renderAlloc(pf); renderEquity(pf);
  const keys = Object.keys(SOURCES), live = keys.filter(k => S.q[k] && S.q[k].live).length;
  $("live-dot").className = "dot " + (live === keys.length ? "live" : live ? "partial" : "off");
  $("live-label").textContent = live === keys.length ? "All feeds live" : `${live}/${keys.length} feeds live`;
  $("last-upd").textContent = tfmt(S.lastUpd, false) + ":" + String(new Date(S.lastUpd).getSeconds()).padStart(2, "0");
}

/* ---------- rendering: committee / static parts ---------- */
function md(s) { return DOMPurify.sanitize(marked.parse(s || "")); }
function renderTimeline() {
  const ev = [], L = S.L, IC = S.IC;
  ev.push({ t: L.inception, h: "Fund incepted", b: `Paper capital ${eur(L.starting_capital, 0)} · base ${esc(L.base_ccy)}`, c: "#64748b" });
  IC.ics.forEach(ic => ev.push({ t: ic.time, h: `IC #${ic.seq}: ${esc(ic.title.replace(/^Apex Horizon Capital\s*[—-]\s*/, ""))}`, b: esc(ic.decision || "") + (ic.chairman ? `<br><span class="muted">${esc(ic.chairman)}</span>` : ""), c: "#3b82f6" }));
  (L.trade_history || []).forEach(t => ev.push({ t: t.time, h: `${esc(t.action)} ${esc(t.symbol)}`, b: `${num(t.qty, 4)} @ ${num(t.price, 4)} · ${eur(t.value_eur)}${t.realized_pnl_eur != null ? ` · realised <span class="${cls(t.realized_pnl_eur)}">${sgnEur(t.realized_pnl_eur)}</span>` : ""}`, c: /BUY/.test(t.action) && !/COVER/.test(t.action) ? "#22d3a6" : "#f43f5e" }));
  IC.rulings.forEach(r => ev.push({ t: r.time, h: "Board ruling (Chairman)", b: esc(r.text), c: "#f59e0b" }));
  IC.research.forEach(r => { const m = /(\d{4}-\d{2}-\d{2}),\s*(\d{2}:\d{2})/.exec(r.date); if (m) ev.push({ t: `${m[1]}T${m[2]}:00+01:00`, h: "Research: " + esc(r.title), b: esc(r.verdict), c: "#a78bfa" }); });
  ev.sort((a, b) => new Date(b.t) - new Date(a.t));
  $("timeline").innerHTML = ev.map(e => `<li style="--c:${e.c}"><div class="t">${tfull(e.t)}</div><div class="h">${e.h}</div><div class="b">${e.b}</div></li>`).join("");
}
function renderRulings() {
  $("rulings").innerHTML = S.IC.rulings.map(r => `<div class="ruling"><div class="t">${tfull(r.time)}</div>${esc(r.text)}</div>`).join("") || '<div class="muted">None.</div>';
  $("vetoes").innerHTML = (S.L.vetoed || []).map(v => `<div class="veto"><b>${esc(v.idea)}</b> <span class="pill bad">VETO</span><div class="small muted">by ${esc(v.by.join(", "))} · ${esc(v.reason)}</div></div>`).join("");
}
function renderMinutes() {
  $("minutes").innerHTML = S.IC.ics.slice().reverse().map((ic, i) => `<details class="min" ${i === 0 ? "open" : ""}><summary><span>IC #${ic.seq} · ${esc(ic.title.replace(/^#\s*/, ""))}</span><span class="muted small">${tfull(ic.time)} · ${esc(ic.file)}</span></summary><div class="md">${md(ic.markdown)}</div></details>`).join("");
}
const AV = { elena: "#22d3a6", kenji: "#3b82f6", marcus: "#a78bfa", sofia: "#f43f5e", tomas: "#f59e0b" };
function renderTeam() {
  const lastIC = S.IC.ics[S.IC.ics.length - 1];
  const lead = [
    { n: "Karli", r: "Chairman", c: "#e2e8f0", v: S.IC.rulings.length ? `Latest ruling (${tfmt(S.IC.rulings.at(-1).time)} CET): ${S.IC.rulings.at(-1).text}` : "", ini: "K" },
    { n: S.meta.ceo, r: "CEO", c: "#7dd3fc", v: lastIC ? `Latest decision, IC #${lastIC.seq} (${tfmt(lastIC.time)} CET): ${lastIC.decision || ""}` : "", ini: "GB" },
  ];
  const cards = lead.map(m => `<div class="member"><div class="top"><div class="avatar" style="background:${m.c}">${esc(m.ini)}</div><div><h3>${esc(m.n)}</h3><div class="role">${esc(m.r)}</div></div></div><div class="view">${esc(m.v)}</div></div>`);
  S.IC.team.forEach(t => {
    const ini = t.name.replace("Dr. ", "").split(" ").map(x => x[0]).join("");
    const older = t.history.slice(0, -1).reverse();
    cards.push(`<div class="member"><div class="top"><div class="avatar" style="background:${AV[t.key]}">${esc(ini)}</div><div><h3>${esc(t.name)}</h3><div class="role">${esc(t.role)} · ${esc(t.dept)}</div></div></div>
      ${t.latest ? `<div class="small muted">Latest view · IC #${S.IC.ics.find(i => i.id === t.latest.ic).seq} · ${tfmt(t.latest.time)} CET</div><div class="view">${esc(t.latest.text)}</div>` : '<div class="muted">No recorded view yet.</div>'}
      ${older.length ? `<details><summary>Earlier views (${older.length})</summary>${older.map(o => `<p><b>IC #${S.IC.ics.find(i => i.id === o.ic).seq}</b> · ${esc(o.bullets.slice(0, 4).join(" • ") || o.text)}</p>`).join("")}</details>` : ""}</div>`);
  });
  $("teamcards").innerHTML = cards.join("");
}
function tableHTML(t, hl) {
  if (!t) return "";
  const c = s => esc(String(s).replace(/\*\*/g, ""));
  return `<div class="tscroll"><table><thead><tr>${t.head.map(h => `<th>${c(h)}</th>`).join("")}</tr></thead><tbody>${t.rows.map(r => `<tr ${hl && hl(r) ? 'style="background:#a78bfa12"' : ""}>${r.map(x => `<td class="num">${c(x)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`;
}
function renderResearch() {
  const rs = S.IC.research; if (!rs.length) { $("research-card").innerHTML = "<h2>Research</h2><div class='muted'>No research reports.</div>"; return; }
  const vid = S.IC.ics.find(i => i.kind === "review");
  $("research-card").innerHTML = rs.map(r => {
    const comb = r.primary_table && r.primary_table.rows.find(x => /Combined/.test(x[0]));
    const H = r.primary_table ? r.primary_table.head : [];
    const col = n => comb ? String(comb[H.indexOf(n)] || "").replace(/\*\*/g, "") : "—";
    const cd = r.costdrag_table ? r.costdrag_table.rows.filter(x => /OOS/.test(x[1])) : [];
    const CH = r.costdrag_table ? r.costdrag_table.head : [];
    return `<div class="rs-head"><div><div class="card-h" style="margin:0"><h2>Research · ${esc(r.title)}</h2></div><div class="small muted">${esc(r.date)} · ${esc(r.file)}</div></div>
        <div style="text-align:right"><div class="verdict">REJECTED · ${esc(r.verdict || "")}</div><div class="small muted">Board rule: ${esc(r.board_rule || "")}</div></div></div>
      ${vid ? `<div class="cmp" style="margin-top:14px"><div><div class="small muted">What the video claimed</div><div style="margin-top:4px">${esc(vid.claims || "")}</div><div class="small muted" style="margin-top:6px">Method: ${esc(vid.method || "")}</div></div>
        <div><div class="small muted">What Kenji's backtest found (out-of-sample, after costs)</div><div style="margin-top:4px">Combined BTC+ETH viable-stop trades: <b>${col("n")}</b> trades, win rate <b>${col("Win rate")}</b>, expectancy <b class="dn">${col("E[R] after costs")}R</b>, profit factor <b>${col("Profit factor")}</b>.
          Break-even win rate after costs: <b>${esc(r.breakeven_winrate || "—")}</b>. Costs: ${esc(r.costs || "")} per side (${r.roundtrip_bps ?? "—"} bps round trip).</div></div></div>` : ""}
      <div class="stats">
        <div class="stat"><div class="l">OOS trades (viable stops)</div><div class="v num">${col("n")}</div><div class="l">rule needs ≥300</div></div>
        <div class="stat"><div class="l">OOS expectancy after costs</div><div class="v num dn">${col("E[R] after costs")}R</div><div class="l">rule needs &gt; 0</div></div>
        <div class="stat"><div class="l">OOS win rate</div><div class="v num">${col("Win rate")}</div><div class="l">video claimed 86.67%</div></div>
        <div class="stat"><div class="l">Break-even win rate</div><div class="v num wn">${esc(r.breakeven_winrate || "—")}</div><div class="l">with ~16 bp stops</div></div>
        ${cd.map(x => `<div class="stat"><div class="l">${esc(x[0])} OOS, no stop filter</div><div class="v num dn">${esc(x[CH.indexOf("Win rate")])}</div><div class="l">win rate · ${esc(x[CH.indexOf("n")])} trades · cost &gt; 1R on ${esc(x[CH.indexOf("Trades with cost > 1R")])}</div></div>`).join("")}
      </div>
      <details class="min"><summary><span>Board-rule check (${r.board_rule_table ? r.board_rule_table.rows.length : 0} OOS tests)</span><span class="muted small">REPORT.md §10</span></summary><div class="md">${tableHTML(r.board_rule_table)}</div></details>
      <details class="min"><summary><span>Primary results: after costs, viable stops (RR 1:1)</span><span class="muted small">REPORT.md §5</span></summary><div class="md">${tableHTML(r.primary_table, x => /OOS/.test(x[1]))}</div></details>
      <details class="min"><summary><span>Cost drag: no minimum-stop filter</span><span class="muted small">REPORT.md §7</span></summary><div class="md">${tableHTML(r.costdrag_table)}</div></details>
      <details class="min"><summary><span>Full report</span><span class="muted small">${esc(r.file)}</span></summary><div class="md">${md(r.markdown)}</div></details>`;
  }).join("<hr>");
}
function renderLog() {
  const T = (S.L.trade_history || []).slice().reverse();
  $("tradelog").innerHTML = `<div class="tscroll"><table class="stack"><thead><tr><th>Time (CET)</th><th>Action</th><th>Symbol</th><th>Qty</th><th>Price</th><th>Value</th><th>Fees</th><th>Realised</th><th>Cash after</th><th>Note</th></tr></thead><tbody>
    ${T.map(t => `<tr><td data-l="Time" class="num">${tfmt(t.time)}</td><td data-l="Action"><span class="pill ${/BUY/.test(t.action) && !/COVER/.test(t.action) ? "ok" : "bad"}">${esc(t.action)}</span>${t.reason ? ` <span class="pill warn">${esc(t.reason)}</span>` : ""}</td>
      <td data-l="Symbol"><b>${esc(t.symbol)}</b></td><td data-l="Qty" class="num">${num(t.qty, 4)}</td><td data-l="Price" class="num">${num(t.price, 4)}</td>
      <td data-l="Value" class="num">${t.value_eur != null ? eur(t.value_eur) : "—"}</td><td data-l="Fees" class="num">${eur(t.fees_eur)}</td>
      <td data-l="Realised" class="num ${cls(t.realized_pnl_eur)}">${t.realized_pnl_eur != null ? sgnEur(t.realized_pnl_eur) : "—"}</td><td data-l="Cash after" class="num">${eur(t.cash_after)}</td>
      <td data-l="Note" class="full small muted" style="min-width:220px">${esc(t.note || "")}</td></tr>`).join("")}</tbody></table></div>`;
}
function renderStatic() {
  renderTimeline(); renderRulings(); renderMinutes(); renderTeam(); renderResearch(); renderLog();
  $("hdr-mode").textContent = S.L.mode;
  $("foot-meta").innerHTML = `Ledger as of last mark ${tfull(S.meta.as_of)} · ${S.IC.ics.length} IC sessions · ${S.IC.rulings.length} board rulings · CEO ${esc(S.meta.ceo)} · Chairman ${esc(S.meta.chairman)}`;
}

/* ---------- boot ---------- */
async function loadData() {
  const [a, b] = await Promise.all([getJSON("data/ledger.json?cb=" + Date.now()), getJSON("data/ic.json?cb=" + Date.now())]);
  const changed = !S.meta || S.meta.as_of !== a.meta.as_of || JSON.stringify(S.IC && S.IC.rulings) !== JSON.stringify(b.rulings) || (S.IC && S.IC.ics.length) !== b.ics.length;
  S.L = a.ledger; S.meta = a.meta; S.IC = b;
  if (changed) renderStatic();
}
function initNav() {
  const links = [...document.querySelectorAll("#tabs a")];
  const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) links.forEach(l => l.classList.toggle("active", l.getAttribute("href") === "#" + e.target.id)); }), { rootMargin: "-40% 0px -55% 0px" });
  document.querySelectorAll("section.anchor").forEach(s => io.observe(s));
}
async function boot() {
  Chart.defaults.font.family = "Inter, system-ui, sans-serif"; Chart.defaults.color = "#8b9ab3";
  try { await loadData(); } catch (e) { document.querySelector("main").insertAdjacentHTML("afterbegin", `<div class="err-banner">Could not load data files: ${esc(e.message)}</div>`); return; }
  renderLive();               // ledger marks first, then live
  await refreshPrices();
  initNav();
  $("refresh").onclick = () => refreshPrices();
  setInterval(() => { S.countdown--; $("next-in").textContent = Math.max(0, S.countdown); if (S.countdown <= 0) refreshPrices(); }, 1000);
  setInterval(() => loadData().then(renderLive).catch(() => {}), DATA_REFRESH_S * 1000);
  document.addEventListener("visibilitychange", () => { if (!document.hidden) refreshPrices(); });
  window.__apexReady = true;
}
boot();
